-- Run after 003. Adds quotation replies and private customer documents.
USE yeha_group;
CREATE TABLE IF NOT EXISTS quotation_responses(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,quotation_id BIGINT UNSIGNED NOT NULL,admin_id BIGINT UNSIGNED NULL,price DECIMAL(12,2) NULL,message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(quotation_id) REFERENCES quotations(id) ON DELETE CASCADE,FOREIGN KEY(admin_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS uploaded_documents(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,quotation_id BIGINT UNSIGNED NULL,original_name VARCHAR(190) NOT NULL,stored_name VARCHAR(80) NOT NULL,mime VARCHAR(80) NOT NULL,size_bytes INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(quotation_id) REFERENCES quotations(id) ON DELETE SET NULL) ENGINE=InnoDB;
